-- =============================================================================================
-- Played games (owner request, 2026-11-10):
--   * public or private: a public game shows its result, battle report, photos and comments to
--     everyone; a private one only to its players (and admins). Public by default (owner choice).
--     The game itself stays listed (date, place, seats): only what happened at the table is hidden.
--   * the host marks a game as finished (any time after its start): a "finished" badge, and the
--     players are told to add the result.
--   * public comments: any signed-in player can comment on a public game once it has started; the
--     players of a private game can comment among themselves. 20 comments an hour at most, the
--     author, the host or an admin deletes a comment, three reports hide it.
-- =============================================================================================

alter table public.games add column if not exists is_public boolean not null default true;
alter table public.games add column if not exists finished_at timestamptz;

alter table public.notifications drop constraint if exists notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check (kind in (
  'join_request', 'join_answer', 'game_match', 'report_to_confirm', 'report_answer', 'message',
  'game_message', 'league_game', 'round_paired', 'match_to_confirm', 'match_answer', 'contest_results',
  'round_schedule', 'mentor_request', 'mentor_answer', 'game_deleted', 'suggestion',
  'game_finished', 'game_comment'));

-- What happened at the table can be read: public game, its players, or an admin.
create or replace function public.game_is_visible(p_game uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.games where id = p_game and is_public)
      or public.is_game_participant(p_game)
      or public.is_admin();
$$;
revoke execute on function public.game_is_visible(uuid) from public;
grant execute on function public.game_is_visible(uuid) to anon, authenticated;

drop policy if exists "reports are public" on public.game_reports;
drop policy if exists "reports of visible games" on public.game_reports;
create policy "reports of visible games" on public.game_reports for select using (public.game_is_visible(game_id));
drop policy if exists "results are public" on public.game_results;
drop policy if exists "results of visible games" on public.game_results;
create policy "results of visible games" on public.game_results for select using (public.game_is_visible(game_id));
drop policy if exists "guest results are public" on public.game_guest_results;
drop policy if exists "guest results of visible games" on public.game_guest_results;
create policy "guest results of visible games" on public.game_guest_results for select using (public.game_is_visible(game_id));

-- Report photos: as before (uploader's public profile, or the players), and now only on public games.
drop policy if exists "report photos: readable per uploader profile" on storage.objects;
create policy "report photos: readable per uploader profile" on storage.objects
  for select
  using (bucket_id = 'reports'
         and (public.is_game_participant(((storage.foldername(name))[1])::uuid)
              or (public.profile_is_visible(owner)
                  and exists (select 1 from public.games g where g.id = ((storage.foldername(name))[1])::uuid and g.is_public))));

-- The host shows or hides what happened at the table.
create or replace function public.set_game_public(p_game uuid, p_public boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.games where id = p_game and host_id = auth.uid()) then
    raise exception 'not_host';
  end if;
  update public.games set is_public = coalesce(p_public, true) where id = p_game;
end;
$$;

-- The host marks the game finished (or not, to undo a mistake). Players are told to add the result.
create or replace function public.set_game_finished(p_game uuid, p_finished boolean default true)
returns timestamptz
language plpgsql
security definer
set search_path = public
as $$
declare
  g public.games;
  who text;
  p uuid;
begin
  select * into g from public.games where id = p_game for update;
  if not found or g.host_id is distinct from auth.uid() then
    raise exception 'not_host';
  end if;
  if g.status = 'cancelled' or g.starts_at > now() then
    raise exception 'not_played_yet';
  end if;
  if not coalesce(p_finished, true) then
    update public.games set finished_at = null where id = p_game;
    return null;
  end if;
  if g.finished_at is not null then
    return g.finished_at;
  end if;
  update public.games set finished_at = now() where id = p_game;
  select display_name into who from public.profiles where id = g.host_id;
  for p in select player_id from public.game_players where game_id = p_game and status = 'accepted' loop
    perform public.notify(p, 'game_finished', jsonb_build_object('game_id', p_game, 'game', g.game_system, 'from', who));
  end loop;
  return now();
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Comments
-- ---------------------------------------------------------------------------------------------
create table if not exists public.game_comments (
  id         uuid primary key default gen_random_uuid(),
  game_id    uuid not null references public.games (id) on delete cascade,
  author_id  uuid not null references public.profiles (id) on delete cascade,
  body       text not null check (char_length(btrim(body)) between 1 and 500),
  is_hidden  boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists game_comments_game_idx on public.game_comments (game_id, created_at);
create index if not exists game_comments_author_idx on public.game_comments (author_id, created_at);

alter table public.game_comments enable row level security;
revoke insert, update, delete on public.game_comments from anon, authenticated;
drop policy if exists "comments of visible games" on public.game_comments;
create policy "comments of visible games" on public.game_comments
  for select using (public.game_is_visible(game_id) and (not is_hidden or author_id = auth.uid() or public.is_admin()));

drop trigger if exists game_comments_block_suspended on public.game_comments;
create trigger game_comments_block_suspended before insert on public.game_comments
  for each row execute function public.block_suspended('author_id');

alter type public.report_target add value if not exists 'comment';

create or replace function public.add_game_comment(p_game uuid, p_body text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  g public.games;
  body text := btrim(coalesce(p_body, ''));
  who text;
  new_id uuid;
  p uuid;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;
  select * into g from public.games where games.id = p_game;
  if not found or g.status = 'cancelled' or g.starts_at > now() then
    raise exception 'not_played_yet';
  end if;
  if not (g.is_public or public.is_game_participant(p_game)) then
    raise exception 'forbidden';
  end if;
  if char_length(body) not between 1 and 500 then
    raise exception 'bad_comment';
  end if;
  if (select count(*) from public.game_comments where author_id = auth.uid() and created_at > now() - interval '1 hour') >= 20 then
    raise exception 'rate_limited';
  end if;
  insert into public.game_comments (game_id, author_id, body) values (p_game, auth.uid(), body) returning game_comments.id into new_id;
  -- Players of the game hear about it, once until they open their notifications.
  select display_name into who from public.profiles where profiles.id = auth.uid();
  for p in
    select g.host_id union select player_id from public.game_players where game_id = p_game and status = 'accepted'
  loop
    if p <> auth.uid() and not exists (select 1 from public.notifications n
                                        where n.user_id = p and n.kind = 'game_comment' and n.read_at is null
                                          and n.payload ->> 'game_id' = p_game::text) then
      perform public.notify(p, 'game_comment', jsonb_build_object('game_id', p_game, 'game', g.game_system, 'from', who));
    end if;
  end loop;
  return new_id;
end;
$$;

create or replace function public.delete_game_comment(p_comment uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.game_comments c
   where c.id = p_comment
     and (c.author_id = auth.uid() or public.is_game_host(c.game_id) or public.is_admin());
  if not found then
    raise exception 'forbidden';
  end if;
end;
$$;

-- Report a comment; three distinct reporters hide it until an admin looks at it.
create or replace function public.report_game_comment(p_comment uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;
  if not exists (select 1 from public.game_comments where id = p_comment) then
    raise exception 'no_comment';
  end if;
  if exists (select 1 from public.reports where reporter_id = auth.uid() and target_type::text = 'comment' and target_id = p_comment::text) then
    return;
  end if;
  insert into public.reports (reporter_id, target_type, target_id, reason)
  values (auth.uid(), 'comment', p_comment::text, left(btrim(coalesce(p_reason, '')), 500));
  if (select count(distinct reporter_id) from public.reports where target_type::text = 'comment' and target_id = p_comment::text and status = 'open') >= 3 then
    update public.game_comments set is_hidden = true where id = p_comment;
  end if;
end;
$$;

revoke execute on function public.set_game_public(uuid, boolean) from public, anon;
revoke execute on function public.set_game_finished(uuid, boolean) from public, anon;
revoke execute on function public.add_game_comment(uuid, text) from public, anon;
revoke execute on function public.delete_game_comment(uuid) from public, anon;
revoke execute on function public.report_game_comment(uuid, text) from public, anon;
grant execute on function public.set_game_public(uuid, boolean) to authenticated;
grant execute on function public.set_game_finished(uuid, boolean) to authenticated;
grant execute on function public.add_game_comment(uuid, text) to authenticated;
grant execute on function public.delete_game_comment(uuid) to authenticated;
grant execute on function public.report_game_comment(uuid, text) to authenticated;

